/**
 * Unit tests for failureAnalyzer.js — gh-136, the AI failure-analyzer leg.
 *
 * The module is the pure half of the failure-analysis state machine:
 *   - the SM-config knob resolution (missing → disabled silently; malformed
 *     → hard error — AC7),
 *   - the same-signature streak math (reusing the gh-1363 normalizer — no
 *     second implementation) and the threshold-crossing rule (AC1/AC2/AC6),
 *   - the analyzer verdict marker (reviewVerdicts house pattern: a machine
 *     parseable `<!-- dmtools:failure-verdict ... -->` comment) and its
 *     machine-identity-gated parse,
 *   - the ONE park-diagnostic comment builder and its idempotency counter
 *     (AC3).
 *
 * The scripted-provider replay of the whole acceptance matrix (AC1–AC5)
 * lives in test_machineSmAgent.js — this file pins the pure contract.
 */
/* global suite, test, assert, loadModule, makeRequire */

function lfrShared() {
    if (!lfrShared.mod) lfrShared.mod = loadModule('js/common/legFailureReport.js', makeRequire({}), {});
    return lfrShared.mod;
}

function rvShared() {
    if (!rvShared.mod) rvShared.mod = loadModule('js/common/reviewVerdicts.js',
        makeRequire({ './machineAuthor.js': maShared() }), {});
    return rvShared.mod;
}

function maShared() {
    if (!maShared.mod) maShared.mod = loadModule('js/common/machineAuthor.js', makeRequire({}), {});
    return maShared.mod;
}

function faShared() {
    if (!faShared.mod) {
        faShared.mod = loadModule('js/common/failureAnalyzer.js', makeRequire({
            './legFailureReport.js': lfrShared(),
            './reviewVerdicts.js': rvShared()
        }), {});
    }
    return faShared.mod;
}

var MARKDOWN = {
    h: function (level, text) {
        var prefix = '';
        for (var i = 0; i < level; i++) prefix += '#';
        return prefix + ' ' + text;
    },
    bold: function (text) { return '**' + text + '**'; },
    inline: function (text) { return '`' + text + '`'; },
    code: function (text) { return '```\n' + text + '\n```'; },
    link: function (text, url) { return '[' + text + '](' + url + ')'; }
};

/** One failure-notice comment body carrying the gh-1363 signature line. */
function failureBody(lfr, workflow, step, message) {
    var sig = lfr.failureSignature({ workflow: workflow, step: step, message: message });
    return lfr.buildFailureComment({
        phase: 'setup', step: step, excerpt: message, signature: sig
    }, MARKDOWN);
}

/** One machine-authored analyzer verdict comment body. */
function verdictComment(fa, record, author) {
    return { user: { login: author || 'github-actions[bot]' },
             body: fa.buildFailureVerdictComment(record) };
}

suite('failureAnalyzer config (gh-136 AC7)', function () {
    var fa = faShared();

    test('missing config disables the feature silently — no error, no behavior change', function () {
        assert.deepEqual(fa.resolveFailureAnalysisConfig(undefined), { enabled: false });
        assert.deepEqual(fa.resolveFailureAnalysisConfig(null), { enabled: false });
    });

    test('an empty block enables the feature with the documented defaults', function () {
        var cfg = fa.resolveFailureAnalysisConfig({});
        assert.equal(cfg.enabled, true);
        assert.equal(cfg.afterFailures, 4, 'the ticket default is 4');
        assert.equal(cfg.blockedLabel, 'sm:leg-blocked');
        assert.equal(cfg.backoff, 1, 'backoff defaults OFF (= no multiplier)');
    });

    test('a fully specified block normalizes verbatim', function () {
        var cfg = fa.resolveFailureAnalysisConfig({
            afterFailures: 3, blockedLabel: 'my:blocked', backoff: 2
        });
        assert.equal(cfg.enabled, true);
        assert.equal(cfg.afterFailures, 3);
        assert.equal(cfg.blockedLabel, 'my:blocked');
        assert.equal(cfg.backoff, 2);
    });

    test('malformed block shapes hard-error (SM start validation)', function () {
        assert.throws(function () { fa.resolveFailureAnalysisConfig('enabled'); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig(4); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig([]); });
    });

    test('malformed afterFailures hard-errors', function () {
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ afterFailures: 'four' }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ afterFailures: 0 }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ afterFailures: -1 }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ afterFailures: 2.5 }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ afterFailures: null }); });
    });

    test('malformed blockedLabel / backoff hard-error', function () {
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ blockedLabel: 42 }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ blockedLabel: '' });
        });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ backoff: 0 }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ backoff: 'slow' }); });
        assert.throws(function () { fa.resolveFailureAnalysisConfig({ backoff: -2 }); });
    });
});

suite('failureAnalyzer streak math (gh-136 AC1/AC2/AC6)', function () {
    var fa = faShared();
    var lfr = lfrShared();

    test('failureStreak counts the trailing same-signature run (multi-failure)', function () {
        var bodies = [
            failureBody(lfr, 'ai-teammate.yml', 'Development Setup', 'npm ci failed'),
            failureBody(lfr, 'ai-teammate.yml', 'Development Setup', 'npm ci failed at 2026-11-04T09:00Z'),
            failureBody(lfr, 'ai-teammate.yml', 'Development Setup', 'npm ci failed run 1234567')
        ];
        var streak = fa.failureStreak(bodies);
        assert.ok(streak, 'a streak exists');
        assert.equal(streak.count, 3, 'three identical failures — noise normalized away');
        assert.ok(streak.signature.indexOf('ai-teammate.yml') !== -1);
        assert.ok(streak.signature.indexOf('Development Setup') !== -1);
    });

    test('different-signature failures never merge into one streak (AC6)', function () {
        var bodies = [
            failureBody(lfr, 'ai-teammate.yml', 'Development Setup', 'npm ci failed'),
            failureBody(lfr, 'ai-teammate.yml', 'Development Setup', 'npm ci failed'),
            failureBody(lfr, 'ai-teammate.yml', 'Rework Push', 'tests red'),
            failureBody(lfr, 'ai-teammate.yml', 'Development Setup', 'npm ci failed')
        ];
        var streak = fa.failureStreak(bodies);
        assert.equal(streak.count, 1, 'the interleaved different signature breaks the streak');
        assert.ok(streak.signature.indexOf('Development Setup') !== -1);
    });

    test('failureStreak is null without failure history', function () {
        assert.equal(fa.failureStreak([]), null);
        assert.equal(fa.failureStreak(['just a human comment']), null);
        assert.equal(fa.failureStreak(null), null);
    });

    test('consumedCount: the analyzed prefix of this signature only, max wins', function () {
        var sig = 'ai-teammate.yml | Development Setup | npm ci failed';
        var other = 'ai-teammate.yml | Rework Push | tests red';
        var verdicts = [
            { signature: sig, classification: 'transient', analyzedAtCount: 4, at: '2026-11-05T10:00:00.000Z' },
            { signature: sig, classification: 'transient', analyzedAtCount: 8, at: '2026-11-05T11:00:00.000Z' },
            { signature: other, classification: 'transient', analyzedAtCount: 99, at: '2026-11-05T12:00:00.000Z' },
            { signature: sig, classification: 'transient', analyzedAtCount: null, at: '2026-11-05T13:00:00.000Z' }
        ];
        assert.equal(fa.consumedCount(verdicts, sig), 8, 'the deepest analysis of THIS signature consumes');
        assert.equal(fa.consumedCount(verdicts, other), 99);
        assert.equal(fa.consumedCount(verdicts, 'unanalyzed | s | m'), 0);
        assert.equal(fa.consumedCount([], sig), 0);
    });

    test('analysisDue: exactly the threshold crossing (AC1 + the AC5 crash latch)', function () {
        var after = 4;
        assert.equal(fa.analysisDue(1, 0, after), false, 'below the threshold: blind retry');
        assert.equal(fa.analysisDue(3, 0, after), false, 'three identical failures: no analyzer dispatch');
        assert.equal(fa.analysisDue(4, 0, after), true, 'the fourth dispatches the analyzer');
        assert.equal(fa.analysisDue(5, 0, after), false, 'past the crossing: blind retry (analyzer crashed — AC5)');
        assert.equal(fa.analysisDue(4, 4, after), false, 'already analyzed and consumed (park resume) — never re-analyze');
        assert.equal(fa.analysisDue(8, 4, after), true, 'a NEW identical streak reaches the threshold again (AC2)');
        assert.equal(fa.analysisDue(7, 4, after), false, 'the new streak is still below the threshold');
        assert.equal(fa.analysisDue(0, 0, after), false);
        assert.equal(fa.analysisDue(null, 0, after), false);
    });

    test('effectiveStreakCount never goes negative on weird markers', function () {
        assert.equal(fa.effectiveStreakCount(2, 5), 0, 'a consumed count above the streak clamps to 0');
        assert.equal(fa.effectiveStreakCount(8, 4), 4);
    });
});

suite('failureAnalyzer verdict marker (gh-136 house protocol)', function () {
    var fa = faShared();

    function record(over) {
        return Object.assign({
            signature: 'ai-teammate.yml | Development Setup | npm ci failed',
            classification: 'transient',
            confidence: 0.82,
            suspected_root_cause: 'runner network outage',
            evidence: ['npm ERR! network ECONNRESET', 'run step exited 1'],
            suggested_fix: 'retry — the outage is transient',
            analyzedAtCount: 4,
            at: '2026-11-05T10:00:00.000Z',
            source: 'failure-analyzer'
        }, over || {});
    }

    test('build → parse round-trip preserves the structured verdict', function () {
        var body = fa.buildFailureVerdictComment(record());
        assert.ok(body, 'a valid record is postable');
        assert.ok(body.indexOf('<!-- dmtools:failure-verdict ') === 0, 'the marker is the FIRST line');
        var rows = [{ user: { login: 'github-actions[bot]' }, body: body }];
        var parsed = fa.parseFailureVerdicts(rows, { authorLogins: ['github-actions[bot]', 'ai-teammate'] });
        assert.equal(parsed.length, 1);
        var v = parsed[0];
        assert.equal(v.classification, 'transient');
        assert.equal(v.confidence, 0.82);
        assert.equal(v.suspected_root_cause, 'runner network outage');
        assert.deepEqual(v.evidence, ['npm ERR! network ECONNRESET', 'run step exited 1']);
        assert.equal(v.suggested_fix, 'retry — the outage is transient');
        assert.equal(v.analyzedAtCount, 4);
        assert.equal(v.signature, 'ai-teammate.yml | Development Setup | npm ci failed');
        assert.equal(v.source, 'failure-analyzer');
    });

    test('marker-hostile free text survives the round-trip', function () {
        var body = fa.buildFailureVerdictComment(record({
            suspected_root_cause: 'the step emits --> mid-log and <!-- looks like a marker'
        }));
        var parsed = fa.parseFailureVerdicts([{ user: { login: 'ai-teammate' }, body: body }],
            { authorLogins: ['ai-teammate'] });
        assert.equal(parsed.length, 1);
        assert.equal(parsed[0].suspected_root_cause, 'the step emits --> mid-log and <!-- looks like a marker');
    });

    test('an unknown classification or a missing signature is never postable', function () {
        assert.equal(fa.buildFailureVerdictComment(record({ classification: 'broken' })), null);
        assert.equal(fa.buildFailureVerdictComment(record({ signature: '' })), null);
        assert.equal(fa.buildFailureVerdictComment(record({ signature: null })), null);
        assert.equal(fa.buildFailureVerdictComment(null), null);
    });

    test('classification admits exactly transient | deterministic-infra', function () {
        assert.deepEqual(fa.CLASSIFICATIONS, ['transient', 'deterministic-infra']);
        var body = fa.buildFailureVerdictComment(record({ classification: 'deterministic-infra' }));
        var parsed = fa.parseFailureVerdicts([{ user: { login: 'ai-teammate' }, body: body }],
            { authorLogins: ['ai-teammate'] });
        assert.equal(parsed[0].classification, 'deterministic-infra');
    });

    test('machine-identity gate: a forged marker from a foreign author is invisible', function () {
        var body = fa.buildFailureVerdictComment(record());
        var rows = [
            { user: { login: 'somehuman' }, body: body },
            { user: { login: 'github-actions[bot]' }, body: body }
        ];
        var parsed = fa.parseFailureVerdicts(rows, { authorLogins: ['github-actions[bot]'] });
        assert.equal(parsed.length, 1, 'only the machine-authored marker is trusted');
        assert.equal(parsed[0].order, 1, 'the trusted record keeps its payload position');
    });

    test('fail closed: no machine logins configured → nothing is trusted', function () {
        var body = fa.buildFailureVerdictComment(record());
        var rows = [{ user: { login: 'ai-teammate' }, body: body }];
        assert.deepEqual(fa.parseFailureVerdicts(rows, {}), []);
        assert.deepEqual(fa.parseFailureVerdicts(rows, { authorLogins: [] }), []);
        assert.deepEqual(fa.parseFailureVerdicts(rows, null), []);
    });

    test('a malformed payload (bad classification / broken JSON) is dropped, never thrown', function () {
        var rows = [
            { user: { login: 'ai-teammate' }, body: '<!-- dmtools:failure-verdict {"classification":"weird","signature":"s"} -->' },
            { user: { login: 'ai-teammate' }, body: '<!-- dmtools:failure-verdict {broken json' },
            { user: { login: 'ai-teammate' }, body: 'no marker at all' }
        ];
        assert.deepEqual(fa.parseFailureVerdicts(rows, { authorLogins: ['ai-teammate'] }), []);
    });

    test('a malformed analyzedAtCount degrades to null (no consumption discount)', function () {
        var body = fa.buildFailureVerdictComment(record({ analyzedAtCount: 'four' }));
        var parsed = fa.parseFailureVerdicts([{ user: { login: 'ai-teammate' }, body: body }],
            { authorLogins: ['ai-teammate'] });
        assert.equal(parsed.length, 1);
        assert.equal(parsed[0].analyzedAtCount, null);
    });

    test('latestVerdictForSignature: newest wins, other signatures ignored', function () {
        var sig = 's | a | m';
        var older = record({ signature: sig, classification: 'transient', at: '2026-11-05T10:00:00.000Z' });
        var newer = record({ signature: sig, classification: 'deterministic-infra', at: '2026-11-05T12:00:00.000Z' });
        var elsewhere = record({ signature: 'other | s | m', classification: 'transient', at: '2026-11-05T13:00:00.000Z' });
        var rows = [
            verdictComment(fa, older),
            verdictComment(fa, elsewhere),
            verdictComment(fa, newer)
        ];
        var parsed = fa.parseFailureVerdicts(rows, { authorLogins: ['github-actions[bot]'] });
        var latest = fa.latestVerdictForSignature(parsed, sig);
        assert.equal(latest.classification, 'deterministic-infra', 'the newest record for THIS signature wins');
        assert.equal(fa.latestVerdictForSignature(parsed, 'unanalyzed | s | m'), null);
        assert.equal(fa.latestVerdictForSignature([], sig), null);
    });
});

suite('failureAnalyzer park diagnostic (gh-136 AC3)', function () {
    var fa = faShared();

    var VERDICT = {
        signature: 'ai-teammate.yml | Development Setup | npm ci failed',
        classification: 'deterministic-infra',
        confidence: 0.9,
        suspected_root_cause: 'setup script pins a deleted registry mirror',
        evidence: ['npm ERR! 404 not-found@1.0.0', 'exit code 1'],
        suggested_fix: 'update .npmrc to the live registry',
        analyzedAtCount: 4,
        at: '2026-11-05T10:00:00.000Z'
    };

    test('the diagnostic carries root cause, evidence, suggested fix and the resume gesture', function () {
        var body = fa.parkDiagnosticComment(VERDICT, 'sm:leg-blocked', MARKDOWN);
        assert.ok(body.indexOf('<!-- dmtools:failure-block ') === 0, 'the marker is the FIRST line');
        assert.ok(body.indexOf('deterministic-infra') !== -1);
        assert.ok(body.indexOf('setup script pins a deleted registry mirror') !== -1, 'root cause named');
        assert.ok(body.indexOf('npm ERR! 404 not-found@1.0.0') !== -1, 'evidence quoted');
        assert.ok(body.indexOf('update .npmrc to the live registry') !== -1, 'suggested fix named');
        assert.ok(body.indexOf('sm:leg-blocked') !== -1, 'the resume gesture names the label');
    });

    test('countParkComments counts machine markers only — quoted text never counts', function () {
        var body = fa.parkDiagnosticComment(VERDICT, 'sm:leg-blocked', MARKDOWN);
        var bodies = [
            'a human comment mentioning failure-block freely',
            body,
            'another human comment',
            fa.parkDiagnosticComment(Object.assign({}, VERDICT, { at: '2026-11-06T10:00:00.000Z' }), 'sm:leg-blocked', MARKDOWN)
        ];
        assert.equal(fa.countParkComments(bodies), 2, 'each machine diagnostic counts');
        assert.equal(fa.countParkComments([]), 0);
        assert.equal(fa.countParkComments(null), 0);
    });

    test('the diagnostic degrades gracefully when verdict fields are absent', function () {
        var body = fa.parkDiagnosticComment({
            signature: 's | a | m', classification: 'deterministic-infra'
        }, 'sm:leg-blocked', MARKDOWN);
        assert.ok(body.indexOf('<!-- dmtools:failure-block ') === 0);
        assert.ok(body.length > 40, 'still a useful human-readable comment');
    });
});

/**
 * failureAnalyzer.js — gh-136, the AI failure-analyzer leg (pure half).
 *
 * The machine SM used to re-dispatch failed legs unconditionally. That is
 * correct for transient causes (network outages, runner glitches, API
 * quota — retrying IS the resilience), but a deterministic failure (repo
 * state, pipeline config, setup code) burns a runner every tick forever.
 * A dumb signature-count circuit breaker is explicitly rejected (owner
 * decision): identical-looking failures can be transient, so a counter
 * must never stop the loop — only an agent that READS the failures and
 * UNDERSTANDS the cause may.
 *
 * This module is the SM-side contract of that analyzer:
 *
 *   1. config — `failureAnalysis` in the SM config. Missing → the feature
 *      is disabled silently (today's blind-retry behavior until the owner
 *      enables it); malformed → a hard validation error at SM start
 *      (resolveFailureAnalysisConfig throws — the house rule).
 *   2. streak — the trailing same-signature failure run, derived from the
 *      gh-1363 machine-readable `failure-signature:` lines (the issue-01
 *      normalizer is REUSED here — no second implementation). Analysis is
 *      due at the EXACT threshold crossing: streak-minus-consumed equals
 *      `afterFailures`. The strict equality is the fail-safe: when the
 *      analyzer leg itself crashed (no verdict, nothing consumed), the
 *      streak moves past the threshold and blind retries continue — a
 *      broken analyzer must never stop retries nor retry itself every tick.
 *   3. verdict — the analyzer leg stamps ONE machine-parseable marker
 *      comment on the issue (the reviewVerdicts house protocol):
 *      `<!-- dmtools:failure-verdict {...} -->` carrying
 *      { classification: transient | deterministic-infra, confidence,
 *        suspected_root_cause, evidence, suggested_fix, analyzedAtCount,
 *        signature, at, source }. Trusted only from machine identities
 *        (the gh-807 rule — a forged marker must never park an issue).
 *   4. park — the SM applies a `deterministic-infra` verdict: label the
 *      issue (name configurable) and post ONE diagnostic comment (root
 *      cause + evidence + suggested fix), then stop re-dispatching. The
 *      ONE-comment idempotency keys on the machine marker, never on text.
 *      Re-dispatch resumes when a human removes the label (or re-assigns
 *      the issue — the assigned event wakes the leg directly).
 *
 * Everything here is pure and GraalJS-clean (var + plain functions,
 * JSON-safe data) — the SM decision core feeds it comment payloads and the
 * analyzer leg (factory side) reuses the same builders to stamp its
 * verdict.
 */

'use strict';

// The issue-01 failure report surface: the normalizer, the signature
// shape and the machine-readable signature lines live there — one
// implementation per the ticket ("Signature counting reuses the
// normalizer from issue 01 — no second implementation").
var legFailureReport = require('./legFailureReport.js');
// The marker plumbing (extractMarkerJson / parseMarkerComments /
// markerSafeReplacer) is the reviewVerdicts house pattern for
// machine-validated structured AI output.
var reviewVerdicts = require('./reviewVerdicts.js');

// ── config (gh-136 AC7) ──────────────────────────────────────────────────

var DEFAULT_AFTER_FAILURES = 4;
var DEFAULT_BLOCKED_LABEL = 'sm:leg-blocked';
var DEFAULT_BACKOFF = 1;

function isPlainObject(value) {
    return !!value && typeof value === 'object' && !Array.isArray(value);
}

function isPositiveInt(value) {
    return typeof value === 'number' && isFinite(value) &&
        Math.floor(value) === value && value >= 1;
}

/**
 * Resolves the `failureAnalysis` SM-config block.
 *   undefined / null            → { enabled: false }  (silently disabled)
 *   a plain object              → validated + defaulted knobs
 *   anything else               → THROWS (hard validation error at SM start)
 * Knob validation (when present): afterFailures a positive integer,
 * blockedLabel a non-empty string, backoff a number >= 1 (1 = off).
 * Unknown keys are ignored (forward-compatible).
 */
function resolveFailureAnalysisConfig(block) {
    if (block === undefined || block === null) return { enabled: false };
    if (!isPlainObject(block)) {
        throw new Error('machineSm: failureAnalysis must be an object ' +
            '(missing config disables the feature silently; a malformed one is a hard error)');
    }
    var cfg = {
        enabled: true,
        afterFailures: DEFAULT_AFTER_FAILURES,
        blockedLabel: DEFAULT_BLOCKED_LABEL,
        backoff: DEFAULT_BACKOFF
    };
    if (block.afterFailures !== undefined && block.afterFailures !== null) {
        if (!isPositiveInt(block.afterFailures)) {
            throw new Error('machineSm: failureAnalysis.afterFailures must be a positive integer, got: ' +
                JSON.stringify(block.afterFailures));
        }
        cfg.afterFailures = block.afterFailures;
    }
    if (block.blockedLabel !== undefined && block.blockedLabel !== null) {
        if (typeof block.blockedLabel !== 'string' || !block.blockedLabel.trim()) {
            throw new Error('machineSm: failureAnalysis.blockedLabel must be a non-empty string, got: ' +
                JSON.stringify(block.blockedLabel));
        }
        cfg.blockedLabel = block.blockedLabel.trim();
    }
    if (block.backoff !== undefined && block.backoff !== null) {
        if (typeof block.backoff !== 'number' || !isFinite(block.backoff) || block.backoff < 1) {
            throw new Error('machineSm: failureAnalysis.backoff must be a number >= 1 (1 = off), got: ' +
                JSON.stringify(block.backoff));
        }
        cfg.backoff = block.backoff;
    }
    return cfg;
}

// ── streak (reuses the issue-01 normalizer) ──────────────────────────────

/**
 * The trailing same-signature failure streak from comment bodies, in
 * order of appearance. Delegates the signature-line parsing and the
 * consecutive counting to the gh-1363 module — one normalizer, one
 * streak definition (the SM and the failure reports can never drift).
 * Returns { signature, count } or null when the issue has no failure
 * history at all.
 */
function failureStreak(bodies) {
    var signatures = legFailureReport.parseSignatureLines(bodies);
    if (!signatures.length) return null;
    var signature = signatures[signatures.length - 1];
    return {
        signature: signature,
        count: legFailureReport.consecutiveRepeatCount(signature, signatures)
    };
}

// ── verdict consumption (gh-136 AC2) ─────────────────────────────────────

/**
 * How much of `signature`'s streak an analyzer verdict already consumed:
 * the deepest analyzedAtCount among THIS signature's verdicts (0 when
 * none). Verdicts for other signatures never consume. A transient
 * verdict consumes its analyzed prefix, so retries continue and a NEW
 * identical streak re-triggers analysis only after the threshold again.
 */
function consumedCount(verdicts, signature) {
    var list = verdicts || [];
    var consumed = 0;
    for (var i = 0; i < list.length; i++) {
        var v = list[i];
        if (!v || v.signature !== signature) continue;
        if (isPositiveInt(v.analyzedAtCount) && v.analyzedAtCount > consumed) {
            consumed = v.analyzedAtCount;
        }
    }
    return consumed;
}

/** The un-analyzed tail of the streak (never negative). */
function effectiveStreakCount(streakCount, consumed) {
    var effective = (streakCount || 0) - (consumed || 0);
    return effective > 0 ? effective : 0;
}

/**
 * The analysis trigger — EXACTLY the threshold crossing. Strict equality
 * is the fail-safe (gh-136 AC5): when the analyzer leg crashes (no
 * verdict → nothing consumed), the streak moves past the threshold,
 * analysisDue goes false, and blind retries continue — a broken analyzer
 * is never re-dispatched every tick and never stops retries.
 */
function analysisDue(streakCount, consumed, afterFailures) {
    if (!isPositiveInt(afterFailures)) return false;
    return effectiveStreakCount(streakCount, consumed) === afterFailures;
}

// ── analyzer verdict marker (reviewVerdicts house protocol) ──────────────

var VERDICT_MARKER_PREFIX = '<!-- dmtools:failure-verdict ';
var VERDICT_MARKER_SUFFIX = ' -->';
var CLASSIFICATIONS = ['transient', 'deterministic-infra'];
var ANALYZE_LEG = 'analyze';
var VERDICT_SOURCE = 'failure-analyzer';
// The park-diagnostic machine marker — the ONE-comment idempotency key.
var PARK_MARKER_PREFIX = '<!-- dmtools:failure-block ';
var PARK_MARKER_SUFFIX = ' -->';

/**
 * Builds the analyzer verdict comment body. record:
 *   signature           — the analyzed failure signature (REQUIRED)
 *   classification      — transient | deterministic-infra (REQUIRED)
 *   confidence          — 0..1 (optional)
 *   suspected_root_cause, suggested_fix — free text (optional)
 *   evidence            — [log lines] (optional)
 *   analyzedAtCount     — the streak count the analysis consumed (optional;
 *                         absent → no consumption discount for transient)
 *   at, source          — timestamp / origin (defaults filled)
 * Returns null when the record is not postable — a head-less verdict must
 * never exist, same rule as the review verdicts.
 */
function buildFailureVerdictComment(record) {
    if (!record || !record.signature || typeof record.signature !== 'string') return null;
    var classification = record.classification;
    if (CLASSIFICATIONS.indexOf(classification) === -1) return null;
    var evidence = Array.isArray(record.evidence)
        ? record.evidence.map(function (line) { return String(line == null ? '' : line); })
        : [];
    var payload = {
        signature: record.signature,
        classification: classification,
        confidence: typeof record.confidence === 'number' ? record.confidence : null,
        suspected_root_cause: record.suspected_root_cause || '',
        evidence: evidence,
        suggested_fix: record.suggested_fix || '',
        analyzedAtCount: isPositiveInt(record.analyzedAtCount) ? record.analyzedAtCount : null,
        at: record.at || new Date().toISOString(),
        source: record.source || VERDICT_SOURCE
    };
    var note = '\uD83E\uDD16 Automated failure analysis. Please do not edit or reply.';
    return reviewVerdicts.MARKER_SAFE_WRAPPER(VERDICT_MARKER_PREFIX,
        JSON.stringify(payload, reviewVerdicts.markerSafeReplacer),
        VERDICT_MARKER_SUFFIX) + '\n' + note;
}

/** One marker payload → the verdict record, or null (strict admission). */
function verdictFromPayload(parsed) {
    if (!isPlainObject(parsed)) return null;
    if (CLASSIFICATIONS.indexOf(parsed.classification) === -1) return null;
    if (!parsed.signature || typeof parsed.signature !== 'string') return null;
    return {
        signature: parsed.signature,
        classification: parsed.classification,
        confidence: typeof parsed.confidence === 'number' ? parsed.confidence : null,
        suspected_root_cause: typeof parsed.suspected_root_cause === 'string' ? parsed.suspected_root_cause : '',
        evidence: Array.isArray(parsed.evidence)
            ? parsed.evidence.map(function (line) { return String(line == null ? '' : line); })
            : [],
        suggested_fix: typeof parsed.suggested_fix === 'string' ? parsed.suggested_fix : '',
        analyzedAtCount: isPositiveInt(parsed.analyzedAtCount) ? parsed.analyzedAtCount : null,
        at: parsed.at || null,
        source: parsed.source || VERDICT_SOURCE
    };
}

/**
 * Parses ALL failure-verdict records from a provider comment payload —
 * comments: [{body}] with author fields (user.login / author.login) when
 * an allowlist is passed. Fail closed: without a machine-identity
 * allowlist NOTHING is trusted (gh-807 — a forged marker must never park
 * an issue). Malformed payloads are dropped, never thrown. Returns
 * records oldest-first (atMs order, payload order as the tiebreak).
 */
function parseFailureVerdicts(comments, opts) {
    var records = reviewVerdicts.parseMarkerComments(comments, opts,
        VERDICT_MARKER_PREFIX, VERDICT_MARKER_SUFFIX, verdictFromPayload, true);
    // parseMarkerComments stamps atMs/order for sorting; the consumers
    // (consumedCount / latestVerdictForSignature) only read protocol
    // fields — keep the ordering metadata too, the machineSm tests pin it.
    return records;
}

/** The newest verdict for one signature, or null. Newest = list order
 *  (parseFailureVerdicts returns oldest-first). */
function latestVerdictForSignature(verdicts, signature) {
    var list = verdicts || [];
    var latest = null;
    for (var i = 0; i < list.length; i++) {
        var v = list[i];
        if (v && v.signature === signature) latest = v;
    }
    return latest;
}

// ── the park diagnostic (gh-136 AC3) ─────────────────────────────────────

var PARK_EVIDENCE_MAX_LINES = 10;

/** Evidence tail for the diagnostic — bounded, machine-marker-safe. */
function parkEvidenceBlock(evidence, m) {
    var lines = (Array.isArray(evidence) ? evidence : [])
        .map(function (line) { return String(line == null ? '' : line); })
        .filter(function (line) { return line.trim(); })
        .slice(-PARK_EVIDENCE_MAX_LINES);
    if (!lines.length) return '';
    return '\n' + m.bold('Evidence (last ' + lines.length + ' lines):') + '\n' +
        m.code(lines.join('\n')) + '\n';
}

/**
 * The ONE park-diagnostic comment: root cause + evidence + suggested fix
 * + the resume gesture. The machine marker is the first line — the
 * SM's ONE-comment idempotency counts these markers, never text.
 * `m` is a commentMarkup-style flavor bag.
 */
function parkDiagnosticComment(verdict, blockedLabel, m) {
    var v = verdict || {};
    var label = blockedLabel || DEFAULT_BLOCKED_LABEL;
    var confidence = (typeof v.confidence === 'number')
        ? ' (confidence ' + v.confidence + ')'
        : '';
    var body = PARK_MARKER_PREFIX +
        JSON.stringify({ signature: v.signature || '', at: v.at || null }) +
        PARK_MARKER_SUFFIX + '\n' +
        m.h(3, '\uD83D\uDED1 AI failure analyzer — leg parked (deterministic infrastructure failure)') + '\n\n' +
        'The failure analyzer read ' + m.bold(String(v.analyzedAtCount || 'repeated') +
        ' consecutive identical failure(s)') + ' and classified the cause as ' +
        m.bold('deterministic-infra') + confidence + ': re-dispatching would fail the same way again, ' +
        'so re-dispatch is STOPPED for this issue.\n\n' +
        m.bold('Failure signature:') + ' ' + m.inline(v.signature || 'unknown') + '\n' +
        (v.suspected_root_cause ? m.bold('Suspected root cause:') + ' ' + v.suspected_root_cause + '\n' : '') +
        parkEvidenceBlock(v.evidence, m) +
        (v.suggested_fix ? m.bold('Suggested fix:') + ' ' + v.suggested_fix + '\n' : '') +
        '\nRe-dispatch resumes when a human removes the ' + m.inline(label) +
        ' label (or re-assigns the issue) — e.g. after applying the suggested fix.';
    return body;
}

/** How many park diagnostics this issue already carries (marker-counted). */
function countParkComments(comments) {
    var list = Array.isArray(comments) ? comments : [];
    var count = 0;
    for (var i = 0; i < list.length; i++) {
        var body = String((list[i] && (list[i].body || list[i])) || '');
        var start = body.indexOf(PARK_MARKER_PREFIX);
        if (start !== -1 && body.indexOf(PARK_MARKER_SUFFIX, start) !== -1) count++;
    }
    return count;
}

module.exports = {
    DEFAULT_AFTER_FAILURES: DEFAULT_AFTER_FAILURES,
    DEFAULT_BLOCKED_LABEL: DEFAULT_BLOCKED_LABEL,
    DEFAULT_BACKOFF: DEFAULT_BACKOFF,
    CLASSIFICATIONS: CLASSIFICATIONS,
    ANALYZE_LEG: ANALYZE_LEG,
    VERDICT_MARKER_PREFIX: VERDICT_MARKER_PREFIX,
    VERDICT_MARKER_SUFFIX: VERDICT_MARKER_SUFFIX,
    PARK_MARKER_PREFIX: PARK_MARKER_PREFIX,
    PARK_MARKER_SUFFIX: PARK_MARKER_SUFFIX,
    resolveFailureAnalysisConfig: resolveFailureAnalysisConfig,
    failureStreak: failureStreak,
    consumedCount: consumedCount,
    effectiveStreakCount: effectiveStreakCount,
    analysisDue: analysisDue,
    buildFailureVerdictComment: buildFailureVerdictComment,
    parseFailureVerdicts: parseFailureVerdicts,
    latestVerdictForSignature: latestVerdictForSignature,
    parkDiagnosticComment: parkDiagnosticComment,
    countParkComments: countParkComments
};

arguments.newText:
var note = '\uD83E\uDD16 Automated failure analysis. Please do not edit or reply.';
return VERDICT_MARKER_PREFIX +
    JSON.stringify(payload, reviewVerdicts.markerSafeReplacer) +
    VERDICT_MARKER_SUFFIX + '\n' + note;

arguments.oldText:
var note = '\uD83E\uDD16 Automated failure analysis. Please do not edit or reply.';
return reviewVerdicts.MARKER_SAFE_WRAPPER(VERDICT_MARKER_PREFIX,
    JSON.stringify(payload, reviewVerdicts.markerSafeReplacer),
    VERDICT_MARKER_SUFFIX) + '\n' + note;

